#[test]
fn sqlite_snapshot_presentation_complete_independent_sql_semantic_cell_extent(){
 use std::{io::Write,process::{Command,Stdio}};
 let cases:serde_json::Value=serde_json::from_str(include_str!("../../\u{1f9eb}\uFE0Ffixtures/\u{1f4cf}\uFE0Fsemantic-cells/\u{1f523}\uFE0F.json")).unwrap();
 for c in cases["cases"].as_array().unwrap(){let mut s=fixture();if let Some(word)=c["word"].as_str(){let value=f64::from_bits(u64::from_str_radix(word,16).unwrap());s.source.frame=crate::FigureTileFrame{x:value,y:value,width:value,height:value};s.source.source_aspect=Some(value);s.tiles[0].crop=s.source.frame.clone();}if c["mode"]!="complete"{s.tiles.clear();if c["mode"]=="absent"{s.source.source_aspect=None;s.source.pdf_page=None;}else{s.source.source_aspect=Some(-0.0);s.source.pdf_page=Some(0);}}
  let d=database(&s);let max=c["bytes"].as_u64().unwrap()as usize;let rows=c["rows"].as_u64().unwrap()as usize;
  let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));const names=JSON.parse(process.env.SEMIO_PRESENTATION_EXPECTED_TABLES);if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const actual=d.query("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name").all().map(r=>r.name);if(JSON.stringify(actual)!==JSON.stringify([...names].sort()))throw Error('complete table names');let bytes=0,rows=0;for(const name of names){const actual=d.query('SELECT * FROM "'+name+'"').all();rows+=actual.length;for(const row of actual)for(const v of Object.values(row))bytes+=v===null?0:typeof v==='string'?Buffer.byteLength(v,'utf8'):v instanceof Uint8Array?v.length:8;}if(bytes!==Number(process.env.SEMIO_PRESENTATION_EXPECTED_BYTES)||rows!==Number(process.env.SEMIO_PRESENTATION_EXPECTED_ROWS))throw Error('complete physical SQL cells '+bytes+'/'+rows);d.close();"#;
  let mut child=Command::new("bun").args(["-e",script]).env("SEMIO_PRESENTATION_EXPECTED_TABLES",cases["tables"].to_string()).env("SEMIO_PRESENTATION_EXPECTED_BYTES",max.to_string()).env("SEMIO_PRESENTATION_EXPECTED_ROWS",rows.to_string()).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&file(&s)).unwrap();let observed=child.wait_with_output().unwrap();assert!(observed.status.success(),"{}",String::from_utf8_lossy(&observed.stderr));
  let limits=SqliteDatabaseLimits{max_value_bytes:max,..SqliteDatabaseLimits::default()};assert_eq!(s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),d);let restored=PresentationSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(database(&restored),d);
  let short=SqliteDatabaseLimits{max_value_bytes:max-1,..limits};assert!(s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err());assert!(PresentationSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err());
  for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let expected=native(&s,encoding);assert_eq!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),expected);let restored=PresentationSnapshot::decode_sqlite_snapshot_native(&expected,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(database(&restored),d);assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err(),"{} native encode",c["name"]);assert!(PresentationSnapshot::decode_sqlite_snapshot_native(&expected,&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err(),"{} native decode",c["name"]);}
  eprintln!("[DEBUG] Presentation complete independent SQL cells case={} bytes={max} rows={rows} tables=4 both_native=true",c["name"]);
 }
